contracts/AgencyShareContract.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title AgencyShareContract
 * @notice Secure cryptographic data sharing between agencies.
 *
 * Grants time-boxed, level-scoped access to criminal data between
 * STATE_POLICE, CBI, NIA, COURT, INTERPOL, CUSTOMS and NCB. Every grant,
 * check and revocation is recorded on-chain, giving a transparent and
 * auditable record of who accessed what, when, and why.
 */
contract AgencyShareContract {
    enum Agency { STATE_POLICE, CBI, NIA, COURT, INTERPOL, CUSTOMS, NCB }
    enum AccessLevel { READ_ONLY, FULL_ACCESS, ANALYSIS_ONLY }

    struct SharePermission {
        bytes32 permissionId;
        string dataId;
        string dataType;      // CRIMINAL | CASE | EVIDENCE | NETWORK
        Agency fromAgency;
        Agency toAgency;
        AccessLevel accessLevel;
        uint256 grantedAt;
        uint256 expiresAt;
        bool isActive;
        bytes32 dataHash;
        address grantedBy;
        string purpose;
        uint256 accessCount;
    }

    mapping(bytes32 => SharePermission) private permissions;
    mapping(string => bytes32[]) private permissionsByData;   // dataId => ids
    mapping(Agency => bytes32[]) private permissionsByAgency; // toAgency => ids
    mapping(bytes32 => string) private revokeReasons;

    event AccessGranted(
        bytes32 permissionId,
        string dataId,
        Agency fromAgency,
        Agency toAgency,
        uint256 expires
    );
    event AccessRevoked(bytes32 permissionId, string reason, address revokedBy);
    event AccessChecked(bytes32 permissionId, Agency agency, uint256 timestamp);
    event AccessExpired(bytes32 permissionId, string dataId);

    /// Grant access to another agency. Returns the permission id.
    function grantAccess(
        string calldata dataId,
        string calldata dataType,
        Agency toAgency,
        Agency fromAgency,
        AccessLevel accessLevel,
        uint256 durationHours,
        bytes32 dataHash,
        string calldata purpose
    ) external returns (bytes32) {
        bytes32 permissionId = keccak256(
            abi.encodePacked(dataId, toAgency, fromAgency, block.timestamp, msg.sender)
        );
        require(bytes(permissions[permissionId].dataId).length == 0, "Permission exists");

        permissions[permissionId] = SharePermission({
            permissionId: permissionId,
            dataId: dataId,
            dataType: dataType,
            fromAgency: fromAgency,
            toAgency: toAgency,
            accessLevel: accessLevel,
            grantedAt: block.timestamp,
            expiresAt: block.timestamp + (durationHours * 1 hours),
            isActive: true,
            dataHash: dataHash,
            grantedBy: msg.sender,
            purpose: purpose,
            accessCount: 0
        });
        permissionsByData[dataId].push(permissionId);
        permissionsByAgency[toAgency].push(permissionId);

        emit AccessGranted(
            permissionId,
            dataId,
            fromAgency,
            toAgency,
            permissions[permissionId].expiresAt
        );
        return permissionId;
    }

    /// Check whether a permission grants access right now.
    function checkAccess(bytes32 permissionId)
        external
        view
        returns (bool hasAccess, AccessLevel level)
    {
        SharePermission storage p = permissions[permissionId];
        if (bytes(p.dataId).length == 0) {
            return (false, AccessLevel.READ_ONLY);
        }
        if (!p.isActive) {
            return (false, AccessLevel.READ_ONLY);
        }
        if (block.timestamp > p.expiresAt) {
            return (false, AccessLevel.READ_ONLY);
        }
        return (true, p.accessLevel);
    }

    /// Revoke a permission.
    function revokeAccess(bytes32 permissionId, string calldata reason) external {
        require(bytes(permissions[permissionId].dataId).length > 0, "Permission not found");
        permissions[permissionId].isActive = false;
        revokeReasons[permissionId] = reason;
        emit AccessRevoked(permissionId, reason, msg.sender);
    }

    /// Extend a permission by additional hours.
    function extendAccess(bytes32 permissionId, uint256 additionalHours) external {
        SharePermission storage p = permissions[permissionId];
        require(bytes(p.dataId).length > 0, "Permission not found");
        require(p.isActive, "Permission inactive");
        p.expiresAt += additionalHours * 1 hours;
    }

    /// Record an access event (increments the counter).
    function logAccess(bytes32 permissionId) external {
        SharePermission storage p = permissions[permissionId];
        require(bytes(p.dataId).length > 0, "Permission not found");
        require(p.isActive, "Permission inactive");
        require(block.timestamp <= p.expiresAt, "Permission expired");
        p.accessCount += 1;
        emit AccessChecked(permissionId, p.toAgency, block.timestamp);
    }

    /// All permissions for a data id.
    function getPermissionsByData(string calldata dataId)
        external
        view
        returns (SharePermission[] memory)
    {
        bytes32[] memory ids = permissionsByData[dataId];
        SharePermission[] memory result = new SharePermission[](ids.length);
        for (uint256 i = 0; i < ids.length; i++) {
            result[i] = permissions[ids[i]];
        }
        return result;
    }

    /// All permissions held by an agency.
    function getPermissionsByAgency(Agency toAgency)
        external
        view
        returns (SharePermission[] memory)
    {
        bytes32[] memory ids = permissionsByAgency[toAgency];
        SharePermission[] memory result = new SharePermission[](ids.length);
        for (uint256 i = 0; i < ids.length; i++) {
            result[i] = permissions[ids[i]];
        }
        return result;
    }

    /// Permissions that have expired (for cleanup/audit).
    function getExpiredPermissions()
        external
        view
        returns (SharePermission[] memory)
    {
        uint256 count = 0;
        for (uint256 i = 0; i < 7; i++) {
            // scan a bounded set of agencies
        }
        // Gather across all agencies (bounded loop over the enum).
        uint256 total = 0;
        for (uint256 a = 0; a < 7; a++) {
            total += permissionsByAgency[Agency(a)].length;
        }
        SharePermission[] memory result = new SharePermission[](total);
        uint256 idx = 0;
        for (uint256 a = 0; a < 7; a++) {
            bytes32[] memory ids = permissionsByAgency[Agency(a)];
            for (uint256 i = 0; i < ids.length; i++) {
                SharePermission storage p = permissions[ids[i]];
                if (p.isActive && block.timestamp > p.expiresAt) {
                    result[idx] = p;
                    idx += 1;
                }
            }
        }
        // Re-pack the result array to the exact length.
        SharePermission[] memory packed = new SharePermission[](idx);
        for (uint256 i = 0; i < idx; i++) {
            packed[i] = result[i];
        }
        return packed;
    }
}

contracts/AuditContract.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title AuditContract
 * @notice Immutable audit trail of every system action.
 *
 * Every VIEW / EDIT / EXPORT / SHARE / DELETE / LOGIN / SEARCH action is
 * permanently recorded. The court can request the complete, tamper-proof
 * history for a criminal or case at any time.
 *
 * Auto-detects suspicious activity:
 *   * the same data accessed 50+ times in a rolling hour
 *   * unauthorized-access results
 */
contract AuditContract {
    struct AuditLog {
        uint256 logId;
        address officerAddress;
        string officerBadgeId;
        string officerDepartment;
        string action;        // VIEW | EDIT | EXPORT | SHARE | DELETE | LOGIN | SEARCH
        string targetId;      // criminal_id or case_id
        string targetType;    // CRIMINAL | CASE | EVIDENCE | REPORT | NETWORK
        uint256 timestamp;
        string ipAddress;     // hashed for privacy
        string result;        // SUCCESS | FAILED | UNAUTHORIZED
        bytes32 dataHash;     // hash of data accessed
        bytes32 sessionHash;
    }

    AuditLog[] private logs;
    mapping(string => uint256[]) private logsByTarget;   // targetId => log ids
    mapping(address => uint256[]) private logsByOfficer; // address => log ids

    // Suspicious-activity detection: per-officer per-hour VIEW counters.
    mapping(address => mapping(uint256 => uint256)) private hourlyViewCount;

    event ActionLogged(uint256 logId, address officer, string action, string targetId, uint256 timestamp);
    event SuspiciousActivity(address officerAddress, string action, uint256 timestamp);

    /// Record one action on the immutable ledger.
    function logAction(
        string calldata officerBadgeId,
        string calldata department,
        string calldata action,
        string calldata targetId,
        string calldata targetType,
        string calldata ipHash,
        string calldata result,
        bytes32 dataHash,
        bytes32 sessionHash
    ) external {
        uint256 logId = logs.length;
        logs.push(
            AuditLog({
                logId: logId,
                officerAddress: msg.sender,
                officerBadgeId: officerBadgeId,
                officerDepartment: department,
                action: action,
                targetId: targetId,
                targetType: targetType,
                timestamp: block.timestamp,
                ipAddress: ipHash,
                result: result,
                dataHash: dataHash,
                sessionHash: sessionHash
            })
        );
        logsByTarget[targetId].push(logId);
        logsByOfficer[msg.sender].push(logId);

        emit ActionLogged(logId, msg.sender, action, targetId, block.timestamp);

        // ── Suspicious-activity auto-detection ────────────────────────────────
        if (keccak256(bytes(result)) == keccak256(bytes("UNAUTHORIZED"))) {
            emit SuspiciousActivity(msg.sender, action, block.timestamp);
        } else if (keccak256(bytes(action)) == keccak256(bytes("VIEW"))) {
            uint256 hour = block.timestamp / 3600;
            hourlyViewCount[msg.sender][hour] += 1;
            if (hourlyViewCount[msg.sender][hour] >= 50) {
                emit SuspiciousActivity(msg.sender, action, block.timestamp);
            }
        }
    }

    /// All logs for a target id (criminal/case).
    function getAuditByTarget(string calldata targetId)
        external
        view
        returns (AuditLog[] memory)
    {
        uint256[] memory ids = logsByTarget[targetId];
        AuditLog[] memory result = new AuditLog[](ids.length);
        for (uint256 i = 0; i < ids.length; i++) {
            result[i] = logs[ids[i]];
        }
        return result;
    }

    /// All actions by an officer address.
    function getAuditByOfficer(address officerAddress)
        external
        view
        returns (AuditLog[] memory)
    {
        uint256[] memory ids = logsByOfficer[officerAddress];
        AuditLog[] memory result = new AuditLog[](ids.length);
        for (uint256 i = 0; i < ids.length; i++) {
            result[i] = logs[ids[i]];
        }
        return result;
    }

    /// Logs within a timestamp range.
    function getAuditByTimeRange(uint256 start, uint256 end)
        external
        view
        returns (AuditLog[] memory)
    {
        uint256 count = 0;
        for (uint256 i = 0; i < logs.length; i++) {
            if (logs[i].timestamp >= start && logs[i].timestamp <= end) {
                count += 1;
            }
        }
        AuditLog[] memory result = new AuditLog[](count);
        uint256 idx = 0;
        for (uint256 i = 0; i < logs.length; i++) {
            if (logs[i].timestamp >= start && logs[i].timestamp <= end) {
                result[idx] = logs[i];
                idx += 1;
            }
        }
        return result;
    }

    /// Total actions ever recorded.
    function getTotalLogsCount() external view returns (uint256) {
        return logs.length;
    }

    /// A specific log entry.
    function getLogById(uint256 logId) external view returns (AuditLog memory) {
        require(logId < logs.length, "Log not found");
        return logs[logId];
    }
}

contracts/CriminalRecordContract.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title CriminalRecordContract
 * @notice Immutable criminal-record change history.
 *
 * Every change to a criminal record (risk score, arrest, conviction, release,
 * profile edit) is appended to an append-only history with the previous and
 * new values, a data hash, and the acting officer. Any party can verify the
 * current database record against the latest on-chain hash to detect tampering.
 */
contract CriminalRecordContract {
    /// One immutable update in a criminal's history.
    struct RecordUpdate {
        uint256 updateId;
        string criminalId;
        string updateType;    // ARREST | RISK_SCORE | CONVICTION | RELEASE | PROFILE
        string previousValue; // JSON of previous state
        string newValue;      // JSON of new state
        address updatedBy;
        string officerBadgeId;
        uint256 timestamp;
        string reason;
        bytes32 dataHash;     // hash of the complete record at this point
        bool isVerified;
    }

    /// Current on-chain state of a criminal record.
    struct CriminalRecord {
        string criminalId;
        bytes32 currentDataHash;
        uint256 createdAt;
        uint256 lastUpdated;
        uint256 updateCount;
        bool isActive;
        bool highRisk;
    }

    mapping(string => CriminalRecord) private records;           // criminalId => state
    mapping(string => RecordUpdate[]) private history;           // criminalId => updates
    mapping(address => bool) public authorizedOfficers;

    uint256 public totalRecords;
    uint256 private nextUpdateId;

    event RecordCreated(string criminalId, bytes32 dataHash, address createdBy);
    event RecordUpdated(string criminalId, string updateType, address officer, uint256 timestamp);
    event RecordVerified(string criminalId, bool isIntact);
    event HighRiskFlagged(string criminalId, address flaggedBy);
    event RecordDeactivated(string criminalId, string reason);

    modifier onlyOfficer() {
        require(authorizedOfficers[msg.sender], "Not an authorized officer");
        _;
    }

    constructor() {
        authorizedOfficers[msg.sender] = true;
    }

    function registerOfficer(address officer) external onlyOfficer {
        authorizedOfficers[officer] = true;
    }

    /// Initialise a criminal record on chain.
    function createRecord(string calldata criminalId, bytes32 dataHash)
        external
        onlyOfficer
    {
        require(bytes(records[criminalId].criminalId).length == 0, "Record already exists");
        records[criminalId] = CriminalRecord({
            criminalId: criminalId,
            currentDataHash: dataHash,
            createdAt: block.timestamp,
            lastUpdated: block.timestamp,
            updateCount: 0,
            isActive: true,
            highRisk: false
        });
        totalRecords += 1;
        emit RecordCreated(criminalId, dataHash, msg.sender);
    }

    /// Append an update to the immutable history.
    function updateRecord(
        string calldata criminalId,
        string calldata updateType,
        string calldata previousValue,
        string calldata newValue,
        string calldata reason,
        bytes32 newHash
    ) external onlyOfficer {
        require(bytes(records[criminalId].criminalId).length > 0, "Record not found");
        require(records[criminalId].isActive, "Record deactivated");

        nextUpdateId += 1;
        history[criminalId].push(
            RecordUpdate({
                updateId: nextUpdateId,
                criminalId: criminalId,
                updateType: updateType,
                previousValue: previousValue,
                newValue: newValue,
                updatedBy: msg.sender,
                officerBadgeId: "",
                timestamp: block.timestamp,
                reason: reason,
                dataHash: newHash,
                isVerified: true
            })
        );

        records[criminalId].currentDataHash = newHash;
        records[criminalId].lastUpdated = block.timestamp;
        records[criminalId].updateCount += 1;

        emit RecordUpdated(criminalId, updateType, msg.sender, block.timestamp);
    }

    /// Full append-only history for a criminal.
    function getFullHistory(string calldata criminalId)
        external
        view
        returns (RecordUpdate[] memory)
    {
        return history[criminalId];
    }

    /// Current on-chain data hash for a criminal.
    function getLatestHash(string calldata criminalId)
        external
        view
        returns (bytes32)
    {
        return records[criminalId].currentDataHash;
    }

    /// Verify that a provided hash matches the on-chain hash (data intact?).
    function verifyCurrentData(string calldata criminalId, bytes32 checkHash)
        external
        view
        returns (bool isIntact)
    {
        CriminalRecord storage rec = records[criminalId];
        if (bytes(rec.criminalId).length == 0) {
            return false;
        }
        bool intact = rec.isActive && rec.currentDataHash == checkHash;
        // Cannot emit events from a view function; the frontend derives the flag.
        return intact;
    }

    /// Flag a record as high risk on chain.
    function markHighRisk(string calldata criminalId) external onlyOfficer {
        require(bytes(records[criminalId].criminalId).length > 0, "Record not found");
        records[criminalId].highRisk = true;
        emit HighRiskFlagged(criminalId, msg.sender);
    }

    /// Soft-delete a record with a reason (history remains immutable).
    function deactivateRecord(string calldata criminalId, string calldata reason)
        external
        onlyOfficer
    {
        require(bytes(records[criminalId].criminalId).length > 0, "Record not found");
        records[criminalId].isActive = false;
        emit RecordDeactivated(criminalId, reason);
    }
}

contracts/EvidenceContract.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title EvidenceContract
 * @notice Makes all investigative evidence tamper-proof.
 *
 * Stores the SHA-256 fingerprint (bytes32) of every evidence file on-chain
 * together with its IPFS CID. Anyone can verify a file against the immutable
 * record — the court can therefore prove whether evidence was altered.
 *
 * Access control:
 *   * only registered officers may add evidence
 *   * only senior officers may mark evidence court-admissible
 *   * anyone (public) may verify evidence integrity
 */
contract EvidenceContract {
    /// A single evidence record.
    struct Evidence {
        string evidenceId;      // unique business id (e.g. EV-2024-001)
        bytes32 fileHash;       // SHA-256 of the file contents
        string ipfsHash;        // IPFS CID where the file is stored
        string criminalId;      // linked criminal
        string caseNumber;      // case reference
        address uploadedBy;     // officer wallet address
        string officerBadgeId;  // officer badge number
        uint256 timestamp;      // block timestamp
        string evidenceType;    // photo | video | document | audio
        string description;
        bool isValid;
        bool courtAdmissible;
    }

    mapping(string => Evidence) private evidences;               // evidenceId => record
    mapping(string => string[]) private evidenceIdsByCase;       // caseNumber => ids
    mapping(string => string[]) private evidenceIdsByCriminal;   // criminalId => ids
    mapping(address => bool) public authorizedOfficers;          // may add evidence
    mapping(address => bool) public seniorOfficers;              // may mark admissible

    uint256 public totalEvidenceCount;

    event EvidenceAdded(
        string evidenceId,
        bytes32 fileHash,
        address officerAddress,
        uint256 timestamp
    );
    event EvidenceVerified(string evidenceId, bool verified, address checkedBy);
    event EvidenceInvalidated(string evidenceId, string reason, address invalidatedBy);
    event MarkedCourtAdmissible(string evidenceId, address markedBy);

    modifier onlyOfficer() {
        require(authorizedOfficers[msg.sender], "Not an authorized officer");
        _;
    }

    modifier onlySeniorOfficer() {
        require(seniorOfficers[msg.sender], "Not a senior officer");
        _;
    }

    constructor() {
        // The deployer is registered as both officer and senior officer.
        authorizedOfficers[msg.sender] = true;
        seniorOfficers[msg.sender] = true;
    }

    /// Register an officer allowed to submit evidence.
    function registerOfficer(address officer) external onlySeniorOfficer {
        authorizedOfficers[officer] = true;
    }

    /// Promote an officer to senior (court-admissible marking rights).
    function promoteSeniorOfficer(address officer) external onlySeniorOfficer {
        seniorOfficers[officer] = true;
    }

    /// Store a new evidence fingerprint on chain.
    function addEvidence(
        string calldata evidenceId,
        bytes32 fileHash,
        string calldata ipfsHash,
        string calldata criminalId,
        string calldata caseNumber,
        string calldata officerBadgeId,
        string calldata evidenceType,
        string calldata description
    ) external onlyOfficer {
        require(bytes(evidenceId).length > 0, "Empty evidence id");
        require(bytes(evidences[evidenceId].evidenceId).length == 0, "Evidence already exists");

        evidences[evidenceId] = Evidence({
            evidenceId: evidenceId,
            fileHash: fileHash,
            ipfsHash: ipfsHash,
            criminalId: criminalId,
            caseNumber: caseNumber,
            uploadedBy: msg.sender,
            officerBadgeId: officerBadgeId,
            timestamp: block.timestamp,
            evidenceType: evidenceType,
            description: description,
            isValid: true,
            courtAdmissible: false
        });

        evidenceIdsByCase[caseNumber].push(evidenceId);
        evidenceIdsByCriminal[criminalId].push(evidenceId);
        totalEvidenceCount += 1;

        emit EvidenceAdded(evidenceId, fileHash, msg.sender, block.timestamp);
    }

    /**
     * Verify a file against the immutable on-chain hash.
     * Returns (verified, message, originalTimestamp).
     */
    function verifyEvidence(
        string calldata evidenceId,
        bytes32 checkHash
    )
        external
        view
        returns (bool verified, string memory message, uint256 originalTimestamp)
    {
        Evidence storage ev = evidences[evidenceId];
        if (bytes(ev.evidenceId).length == 0) {
            return (false, "NOT FOUND - NO BLOCKCHAIN RECORD", 0);
        }
        if (!ev.isValid) {
            return (false, "INVALIDATED - RECORD REVOKED", ev.timestamp);
        }
        if (ev.fileHash == checkHash) {
            return (true, "VERIFIED - NOT TAMPERED", ev.timestamp);
        }
        return (false, "TAMPERED - HASH MISMATCH", ev.timestamp);
    }

    /// Return the full evidence struct.
    function getEvidence(string calldata evidenceId)
        external
        view
        returns (Evidence memory)
    {
        return evidences[evidenceId];
    }

    /// Mark evidence as court-admissible (senior officers only).
    function markCourtAdmissible(string calldata evidenceId) external onlySeniorOfficer {
        require(bytes(evidences[evidenceId].evidenceId).length > 0, "Evidence not found");
        evidences[evidenceId].courtAdmissible = true;
        emit MarkedCourtAdmissible(evidenceId, msg.sender);
    }

    /// Invalidate an evidence record (senior officers only).
    function invalidateEvidence(
        string calldata evidenceId,
        string calldata reason
    ) external onlySeniorOfficer {
        require(bytes(evidences[evidenceId].evidenceId).length > 0, "Evidence not found");
        evidences[evidenceId].isValid = false;
        emit EvidenceInvalidated(evidenceId, reason, msg.sender);
    }

    /// All evidence ids for a case number.
    function getEvidencesByCase(string calldata caseNumber)
        external
        view
        returns (Evidence[] memory)
    {
        string[] memory ids = evidenceIdsByCase[caseNumber];
        Evidence[] memory result = new Evidence[](ids.length);
        for (uint256 i = 0; i < ids.length; i++) {
            result[i] = evidences[ids[i]];
        }
        return result;
    }

    /// All evidence ids for a criminal.
    function getEvidencesByCriminal(string calldata criminalId)
        external
        view
        returns (Evidence[] memory)
    {
        string[] memory ids = evidenceIdsByCriminal[criminalId];
        Evidence[] memory result = new Evidence[](ids.length);
        for (uint256 i = 0; i < ids.length; i++) {
            result[i] = evidences[ids[i]];
        }
        return result;
    }
}

contracts/ReportContract.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title ReportContract
 * @notice Blockchain certificate for every generated report.
 *
 * The SHA-256 of every generated report (PDF/CSV/Excel/JSON) is registered
 * on-chain. Anyone can verify that a presented report is authentic and has
 * not been altered since generation — including the courts.
 */
contract ReportContract {
    struct Report {
        string reportId;
        string reportType;    // CRIMINAL | NETWORK | CASE | EXECUTIVE
        string entityId;      // criminal_id or case_id
        bytes32 reportHash;   // hash of the report content
        address generatedBy;
        string officerBadgeId;
        uint256 generatedAt;
        string classification; // PUBLIC | CONFIDENTIAL | SECRET
        bool isRevoked;
        string revokedReason;
        uint256 version;
        bytes digitalSignature;
    }

    mapping(string => Report) private reports;
    mapping(string => string[]) private reportsByEntity; // entityId => report ids
    mapping(address => bool) public authorizedOfficers;

    uint256 public totalReports;

    event ReportRegistered(string reportId, bytes32 reportHash, address generatedBy);
    event ReportVerified(string reportId, bool isAuthentic, uint256 verifiedAt);
    event ReportRevoked(string reportId, string reason, address revokedBy);

    modifier onlyOfficer() {
        require(authorizedOfficers[msg.sender], "Not an authorized officer");
        _;
    }

    constructor() {
        authorizedOfficers[msg.sender] = true;
    }

    function registerOfficer(address officer) external onlyOfficer {
        authorizedOfficers[officer] = true;
    }

    /// Register a new report certificate.
    function registerReport(
        string calldata reportId,
        string calldata reportType,
        string calldata entityId,
        bytes32 reportHash,
        string calldata classification,
        bytes calldata signature
    ) external onlyOfficer {
        require(bytes(reports[reportId].reportId).length == 0, "Report already registered");

        reports[reportId] = Report({
            reportId: reportId,
            reportType: reportType,
            entityId: entityId,
            reportHash: reportHash,
            generatedBy: msg.sender,
            officerBadgeId: "",
            generatedAt: block.timestamp,
            classification: classification,
            isRevoked: false,
            revokedReason: "",
            version: 1,
            digitalSignature: signature
        });
        reportsByEntity[entityId].push(reportId);
        totalReports += 1;

        emit ReportRegistered(reportId, reportHash, msg.sender);
    }

    /// Verify that a report file matches its on-chain hash.
    function verifyReport(string calldata reportId, bytes32 checkHash)
        external
        view
        returns (bool isAuthentic)
    {
        Report storage rep = reports[reportId];
        if (bytes(rep.reportId).length == 0) {
            return false;
        }
        return !rep.isRevoked && rep.reportHash == checkHash;
    }

    /// Revoke (invalidate) a report certificate.
    function revokeReport(string calldata reportId, string calldata reason)
        external
        onlyOfficer
    {
        require(bytes(reports[reportId].reportId).length > 0, "Report not found");
        reports[reportId].isRevoked = true;
        reports[reportId].revokedReason = reason;
        emit ReportRevoked(reportId, reason, msg.sender);
    }

    /// Register a new version of a report.
    function updateReport(
        string calldata reportId,
        bytes32 newHash,
        uint256 newVersion
    ) external onlyOfficer {
        require(bytes(reports[reportId].reportId).length > 0, "Report not found");
        reports[reportId].reportHash = newHash;
        reports[reportId].version = newVersion;
    }

    /// Full report certificate metadata.
    function getReport(string calldata reportId)
        external
        view
        returns (Report memory)
    {
        return reports[reportId];
    }

    /// All reports for an entity.
    function getReportsByEntity(string calldata entityId)
        external
        view
        returns (Report[] memory)
    {
        string[] memory ids = reportsByEntity[entityId];
        Report[] memory result = new Report[](ids.length);
        for (uint256 i = 0; i < ids.length; i++) {
            result[i] = reports[ids[i]];
        }
        return result;
    }
}

